insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-111","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A conductivity cell of constant $1.5\\ \\mathrm{cm^{-1}}$ reads $G = 0.020\\ \\mathrm{S}$ for a solution. The specific conductivity is","options":["$0.030\\ \\mathrm{S\\ cm^{-1}}$","$0.013\\ \\mathrm{S\\ cm^{-1}}$","$0.075\\ \\mathrm{S\\ cm^{-1}}$","$1.5\\ \\mathrm{S\\ cm^{-1}}$"],"answer_index":0,"explanation":"$\\kappa = G \\times (\\ell/A) = 0.020 \\times 1.5 = 0.030\\ \\mathrm{S\\ cm^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-112","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If $\\kappa = 0.0050\\ \\mathrm{S\\ cm^{-1}}$ for a $0.020\\ \\mathrm{M}$ solution, $\\Lambda_m$ in S cm$^2$ mol$^{-1}$ equals","options":["250","0.25","4.0","100"],"answer_index":0,"explanation":"$\\Lambda_m = 1000\\,\\kappa/c = 1000 \\times 0.0050 / 0.020 = 250\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-113","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 0.10 M KCl standard with $\\kappa = 0.0129\\ \\mathrm{S\\ cm^{-1}}$ shows $R = 86\\ \\Omega$ in a cell. The cell constant is nearest","options":["$1.11\\ \\mathrm{cm^{-1}}$","$0.15\\ \\mathrm{cm^{-1}}$","$86\\ \\mathrm{cm^{-1}}$","$0.0129\\ \\mathrm{cm^{-1}}$"],"answer_index":0,"explanation":"$G = 1/86\\ \\mathrm{S}$, so $\\ell/A = \\kappa/G = 0.0129 \\times 86 \\approx 1.11\\ \\mathrm{cm^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-114","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Comparing $\\kappa$ and $\\Lambda_m$ as a strong electrolyte is diluted, the typical pattern is that","options":["$\\kappa$ decreases while $\\Lambda_m$ increases","both $\\kappa$ and $\\Lambda_m$ fall sharply","both $\\kappa$ and $\\Lambda_m$ rise equally","$\\Lambda_m$ falls while $\\kappa$ stays constant"],"answer_index":0,"explanation":"Fewer ions per cm$^3$ lower $\\kappa$, but each mole of electrolyte contributes more free ionic mobility, so $\\Lambda_m$ rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-115","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The slight increase of $\\Lambda_m$ of NaCl on dilution is attributed mainly to","options":["weaker interionic attractions, so ions migrate faster","fresh ionisation of previously undissociated NaCl molecules","a change in the Faraday constant","conversion of NaCl into a weak electrolyte"],"answer_index":0,"explanation":"NaCl is already fully dissociated. Dilution reduces ion-atmosphere drag (Debye–Hückel–Onsager), raising molar conductivity a little.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-116","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 0.050 M solution in a cell of constant $1.20\\ \\mathrm{cm^{-1}}$ has $R = 50\\ \\Omega$. $\\Lambda_m$ of the solute is","options":["$480\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$24\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$0.48\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$1200\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$"],"answer_index":0,"explanation":"$\\kappa = (1/50)\\times 1.20 = 0.024\\ \\mathrm{S\\ cm^{-1}}$; then $\\Lambda_m = 1000\\times 0.024/0.050 = 480\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-117","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Kohlrausch's law of independent migration states that $\\Lambda_m^\\circ$ of an electrolyte is","options":["the sum of the limiting ionic conductivities of its cation and anion","equal to the product $\\lambda_+^\\circ \\times \\lambda_-^\\circ$","independent of the identities of the two ions","measurable only for metals, not for salts"],"answer_index":0,"explanation":"At infinite dilution each ion migrates independently, so $\\Lambda_m^\\circ = \\nu_+\\lambda_+^\\circ + \\nu_-\\lambda_-^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-118","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a 1:1 salt MX the limiting molar conductivity may be written","options":["$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) + \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+)/\\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) - \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = 2\\lambda^\\circ(\\mathrm{M}^+)$ always"],"answer_index":0,"explanation":"One mole of MX yields one mole of each ion, so the ionic contributions simply add.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-119","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Limiting molar conductivity of a weak electrolyte such as ethanoic acid is obtained by","options":["combining $\\Lambda_m^\\circ$ values of suitable strong electrolytes, not by plotting $\\Lambda_m$ versus $\\sqrt{c}$","extrapolating a Kohlrausch $\\sqrt{c}$ graph of the weak acid itself","measuring $\\kappa$ of distilled water alone","equating $\\Lambda_m$ at 1 M to $\\Lambda_m^\\circ$"],"answer_index":0,"explanation":"A weak acid is far from fully ionised even when dilute, so the $\\sqrt{c}$ plot does not give a reliable intercept.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-120","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Degree of dissociation of a weak electrolyte is estimated from conductivities as","options":["$\\alpha = \\Lambda_m / \\Lambda_m^\\circ$","$\\alpha = \\Lambda_m^\\circ / \\Lambda_m$","$\\alpha = \\Lambda_m \\times \\Lambda_m^\\circ$","$\\alpha = \\kappa / \\Lambda_m$"],"answer_index":0,"explanation":"At a given concentration the fraction ionised is the ratio of the observed molar conductivity to the infinite-dilution value.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
